head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellInputType]<br/>inputType='custom' 인 Column 의 특정 Body Cell 에 inputType 속성을 설정합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터는 Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다.",
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_item !== 'undefined') {
        $p.data.remove("dlt_item");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 4개 컬럼 모두 inputType=custom + setCellInputTypeCustom=true (typeGetter 미설정) -> setCellInputType 동작 대상.\n[MultiLine] 한 데이터 Row 가 2줄 표시 -> 두 줄은 같은 rowIndex, Column 은 0~3 고유 인덱스 (1줄 col1(0)/col2(1), 2줄 col3(2)/col4(3)).\n[절차] rowIndex(0~1) / columnIndex(0~3) 선택 -> setCellInputType 실행. info={inputType:select, itemSet:dlt_item 바인딩} 고정.\n[확인] 리턴창의 (변경 전 -> 변경 후) Cell inputType / Column inputType(custom 유지). 같은 rowIndex 라도 columnIndex 로 위/아래 Line Cell 을 개별 지정."', '', 'label1');

    // itemSet 바인딩용 DataList (select inputType 용)
    //  ※ createBasicDataList 는 col1~col4 스키마만 생성하므로, itemSet 의 label/value 도 col1/col2 를 사용한다.
    //    (col1=표시 라벨, col2=실제 값)
    $c.gcm.createBasicDataList('', '', 'dlt_item');
    dlt_item.setJSON([
        { "col1": "서울", "col2": "01" },
        { "col1": "부산", "col2": "02" },
        { "col1": "대구", "col2": "03" }
    ]);

    // 본문 DataList (custom 셀 편집용, 초기값 빈값) - 2 데이터 Row (각 Row 가 2줄 표시)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "", "col2": "", "col3": "", "col4": "" },
        { "col1": "", "col2": "", "col3": "", "col4": "" }
    ]);

    // target 생성
    //  - setCellInputTypeCustom="true" : custom 컬럼의 Cell 단위 inputType 변경 허용
    //  - 4개 Body 컬럼 모두 inputType="custom" + typeGetter 미설정 (전제)
    // ★ MultiLine : gBody 에 2개의 row 를 두어 한 데이터 Row 가 2줄에 걸쳐 표시되게 한다.
    //  - 1줄 : col1(idx0) / col2(idx1)
    //  - 2줄 : col3(idx2) / col4(idx3)
    //  - 두 줄은 동일 rowIndex, Column 은 줄에 걸쳐 0~3 고유 인덱스
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" setCellInputTypeCustom="true" dataList="data:dlt_bind" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="col1 (idx0, custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="col2 (idx1, custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="col3 (idx2, custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (idx3, custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" inputType="custom" displayMode="label" value="" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" displayMode="label" value="" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="280" inputType="custom" displayMode="label" value="" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" displayMode="label" value="" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 해당 Cell 을 편집모드(더블클릭과 동일)로 진입시켜 실제로 selectbox 가 셀에 표시되는지 확인한다.
//  ※ MultiLine : 같은 rowIndex 라도 columnInfo(0~3) 로 위/아래 Line Cell 을 개별 지정.
//    td 계산은 colIndex + (rowIndex - (api.rowIndex>0?api.rowIndex:0)) * api.oneRowDataLength 공식 사용.
scwin.isSelectboxShown = function (rowIndex, columnInfo) {
    let api = scwin.target1;
    let colIndex = api.getColumnIndex(columnInfo);
    let cellInfo = api.getCellInfo(colIndex);
    let realRow = api.dataList.getRealRowIndex(rowIndex);
    let cm = cellInfo.cellManagerHashByRowIndex ? cellInfo.cellManagerHashByRowIndex[realRow] : null;
    let td = api._getTDByIndex(colIndex + (rowIndex - (api.rowIndex > 0 ? api.rowIndex : 0)) * api.oneRowDataLength);
    // 실제 더블클릭과 동일한 편집모드 진입 경로(mainDrawController.setEditMode) 사용 -> 정상 selectbox 생성
    try { if (td && typeof api.setEditMode === 'function') api.setEditMode(td); } catch (e) {}
    return !!(td && td.querySelector('[role=combobox]'));
};



scwin.btn_setCellInputType_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());          // MultiLine : 두 줄 모두 동일 rowIndex
    let columnInfo = Number(par_columnIndex.getValue());      // MultiLine : 줄에 걸쳐 0~3 고유 인덱스

    // info : select + itemSet(dlt_item) 바인딩 (col1=라벨, col2=값)
    let info = {
        inputType: "select",
        options: {
            viewType: "default"
        },
        itemSet: {
            nodeset: "data:dlt_item",
            label: "col1",
            value: "col2"
        }
    };

    // 메소드 실행
    scwin.target1.setCellInputType(rowIndex, columnInfo, info);
    try { scwin.target1.refreshCell(rowIndex, columnInfo); } catch (e) {}

    // 셀에 selectbox 가 표시되는지 여부
    let shown = scwin.isSelectboxShown(rowIndex, columnInfo);

    // MultiLine 위/아래 Line 표기 (같은 rowIndex 라도 columnIndex 로 개별 지정)
    let lineNote = (columnInfo <= 1) ? "1줄(col" + (columnInfo + 1) + ")" : "2줄(col" + (columnInfo + 1) + ")";

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellInputType(" + rowIndex + ", " + columnInfo + ", { inputType:'select', itemSet:{...} })"
        + " | 셀에 selectbox 표시 여부 : " + (shown ? "표시됨 (O)" : "미표시 (X)")
        + " | MultiLine 대상 : rowIndex=" + rowIndex + " 의 " + lineNote + " Cell (같은 rowIndex, 고유 columnIndex)");
}
